command_result.command:
mkdir -p /tmp/t1/acc && cd /tmp/t1 && cat > book.json <<'EOF'
{"currencies":{"AAA":{"cash":"whole"},"BBB":{"cash":"0.05"}},"tariffs":{"x":{"currency":"BBB","vat":"0.205","standing":"0.00125","bands":[{"upto":null,"price":"0.12345"}]},"y":{"currency":"AAA","vat":"0.125","standing":"-0.4","bands":[{"upto":null,"price":"0.06165"}]}}}
EOF
cat > acc/a.json <<'EOF'
{"account":"A","tariff":"x","period":{"start":"2026-01-01","end":"2026-01-10"},"readings":[{"kwh":"100"}],"credits":[{"ref":"c","amount":-0.005}]}
EOF
cat > acc/b.json <<'EOF'
{"account":"B","tariff":"y","period":{"start":"2026-01-01","end":"2026-01-10"},"readings":[{"kwh":"200"}],"credits":[{"ref":"c","amount":-9.99}]}
EOF
cat > acc/c.json <<'EOF'
{"account":"C","tariff":"y","period":{"start":"2026-01-01","end":"2026-01-10"},"readings":[{"kwh":"0.4"}],"credits":[{"ref":"c","amount":0}]}
EOF
for r in /tmp/orig /app; do (cd $r; for c in 'batch /tmp/t1/acc' 'batch /tmp/t1/acc --format csv' 'bill /tmp/t1/acc/a.json' 'bill /tmp/t1/acc/b.json --format json' 'bill /tmp/t1/acc/c.json' 'bill /tmp/t1/acc/c.json --format csv' 'tariffs' 'quote y 200 1'; do echo "## $c"; PYTHONPATH=$r python -m meterbill --tariffs /tmp/t1/book.json $c 2>&1; done) > /tmp/out_$(basename $r).txt; done; diff /tmp/out_orig.txt /tmp/out_app.txt && echo SAME; grep -n 'Payable\|^B\|^A\|^C\|0.06' /tmp/out_app.txt | head -30
